  'program.peace.impact4.label': 'Reduction in community disputes',
  'program.peace.story1': "Through the peace circles, I learned to listen to my neighbors' stories. Now we work together on projects that benefit everyone in our village.",
  'program.peace.story1Author': 'Fatima Ahmadi',
  'program.peace.story1Role': 'Community Leader',
  'program.peace.story2': 'The conflict resolution training helped me become a bridge between different groups. Peace is possible when we choose understanding over anger.',
  'program.peace.story2Author': 'Ahmad Rahimi',
  'program.peace.story2Role': 'Youth Peace Ambassador',
  'program.peace.partner1': 'UN Peacebuilding Fund',
